import json
from datetime import datetime

def calculate_cagr(data_json: str) -> dict:
    try:
        data = json.loads(data_json)

        if isinstance(data, dict) and 'start_value' in data and 'end_value' in data:
            start_val = float(data['start_value'])
            end_val = float(data['end_value'])
            years = 0.0
            if 'years' in data or 'num_years' in data:
                years = float(data.get('years') or data.get('num_years'))
            elif 'start_date' in data and 'end_date' in data:
                date_fmt = data.get('date_format', '%Y-%m-%d')
                d1 = datetime.strptime(data['start_date'], date_fmt)
                d2 = datetime.strptime(data['end_date'], date_fmt)
                years = (d2 - d1).days / 365.25
            else:
                return {"status": "ERROR", "error": "Missing duration (years or dates)."}

            if start_val <= 0 or end_val <= 0:
                return {"status": "ERROR", "error": "Start and end values must be greater than zero."}
            if years <= 0:
                return {"status": "ERROR", "error": "Number of years must be greater than zero."}

            cagr = (end_val / start_val) ** (1.0 / years) - 1.0
            return {
                "status": "SUCCESS",
                "cagr": cagr,
                "cagr_percentage": round(cagr * 100, 4),
                "start_value": start_val,
                "end_value": end_val,
                "years": years
            }

        if isinstance(data, dict):
            if 'series' in data:
                data = data['series']
            elif 'dated_series' in data:
                data = data['dated_series']
            else:
                return {"status": "ERROR", "error": "Invalid input object structure."}

        if isinstance(data, list):
            if len(data) < 2:
                return {"status": "ERROR", "error": "Time series must contain at least two data points."}

            if isinstance(data[0], (int, float)):
                series = [float(x) for x in data]
                start_val = series[0]
                end_val = series[-1]
                years = float(len(series) - 1)
                if start_val <= 0 or end_val <= 0:
                    return {"status": "ERROR", "error": "Start and end values must be greater than zero."}
                if years <= 0:
                    return {"status": "ERROR", "error": "Number of years must be greater than zero."}
                cagr = (end_val / start_val) ** (1.0 / years) - 1.0
                return {
                    "status": "SUCCESS",
                    "cagr": cagr,
                    "cagr_percentage": round(cagr * 100, 4),
                    "start_value": start_val,
                    "end_value": end_val,
                    "years": years
                }
            elif isinstance(data[0], (list, dict)):
                parsed = []
                for item in data:
                    if isinstance(item, dict):
                        d_str = item.get("date")
                        val = item.get("value")
                        date_fmt = item.get("date_format", "%Y-%m-%d")
                    elif isinstance(item, (list, tuple)) and len(item) == 2:
                        d_str, val = item[0], item[1]
                        date_fmt = "%Y-%m-%d"
                    else:
                        return {"status": "ERROR", "error": "Invalid time series element format."}

                    if d_str is None or val is None:
                        return {"status": "ERROR", "error": "Missing date or value in time series."}
                    dt = datetime.strptime(str(d_str), date_fmt)
                    parsed.append((dt, float(val)))

                parsed.sort(key=lambda x: x[0])
                d1, start_val = parsed[0]
                d2, end_val = parsed[-1]
                years = (d2 - d1).days / 365.25
                if start_val <= 0 or end_val <= 0:
                    return {"status": "ERROR", "error": "Start and end values must be greater than zero."}
                if years <= 0:
                    return {"status": "ERROR", "error": "End date must be after start date."}
                cagr = (end_val / start_val) ** (1.0 / years) - 1.0
                return {
                    "status": "SUCCESS",
                    "cagr": cagr,
                    "cagr_percentage": round(cagr * 100, 4),
                    "start_value": start_val,
                    "end_value": end_val,
                    "years": years
                }

        return {"status": "ERROR", "error": "Unsupported data format."}
    except Exception as e:
        return {"status": "ERROR", "error": str(e)}
